#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define REG_TILE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum[REG_TILE][REG_TILE] = {0.0f};

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tiles into shared memory with coalesced access
        for (int i = 0; i < REG_TILE; i++) {
            for (int j = 0; j < REG_TILE; j++) {
                int A_row = row + i * (TILE_SIZE / REG_TILE);
                int A_col = tile * TILE_SIZE + threadIdx.x + j * (TILE_SIZE / REG_TILE);
                int B_row = tile * TILE_SIZE + threadIdx.y + i * (TILE_SIZE / REG_TILE);
                int B_col = col + j * (TILE_SIZE / REG_TILE);

                if (A_row < N && A_col < N && threadIdx.y + i * (TILE_SIZE / REG_TILE) < TILE_SIZE && threadIdx.x + j * (TILE_SIZE / REG_TILE) < TILE_SIZE) {
                    As[threadIdx.y + i * (TILE_SIZE / REG_TILE)][threadIdx.x + j * (TILE_SIZE / REG_TILE)] = A[A_row * N + A_col];
                } else if (threadIdx.y + i * (TILE_SIZE / REG_TILE) < TILE_SIZE && threadIdx.x + j * (TILE_SIZE / REG_TILE) < TILE_SIZE) {
                    As[threadIdx.y + i * (TILE_SIZE / REG_TILE)][threadIdx.x + j * (TILE_SIZE / REG_TILE)] = 0.0f;
                }

                if (B_row < N && B_col < N && threadIdx.y + i * (TILE_SIZE / REG_TILE) < TILE_SIZE && threadIdx.x + j * (TILE_SIZE / REG_TILE) < TILE_SIZE) {
                    Bs[threadIdx.y + i * (TILE_SIZE / REG_TILE)][threadIdx.x + j * (TILE_SIZE / REG_TILE)] = B[B_row * N + B_col];
                } else if (threadIdx.y + i * (TILE_SIZE / REG_TILE) < TILE_SIZE && threadIdx.x + j * (TILE_SIZE / REG_TILE) < TILE_SIZE) {
                    Bs[threadIdx.y + i * (TILE_SIZE / REG_TILE)][threadIdx.x + j * (TILE_SIZE / REG_TILE)] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            for (int i = 0; i < REG_TILE; i++) {
                for (int j = 0; j < REG_TILE; j++) {
                    if (threadIdx.y + i * (TILE_SIZE / REG_TILE) < TILE_SIZE && threadIdx.x + j * (TILE_SIZE / REG_TILE) < TILE_SIZE) {
                        sum[i][j] += As[threadIdx.y + i * (TILE_SIZE / REG_TILE)][k] * Bs[k][threadIdx.x + j * (TILE_SIZE / REG_TILE)];
                    }
                }
            }
        }

        __syncthreads();
    }

    // Write results back
    for (int i = 0; i < REG_TILE; i++) {
        for (int j = 0; j < REG_TILE; j++) {
            int out_row = row + i * (TILE_SIZE / REG_TILE);
            int out_col = col + j * (TILE_SIZE / REG_TILE);
            if (out_row < N && out_col < N) {
                C[out_row * N + out_col] = sum[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int block_size = TILE_SIZE / REG_TILE;
    dim3 block(block_size, block_size);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

