import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with vectorized access and unrolling
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1]; // +1 to avoid bank conflicts
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tiles into shared memory with vectorized access when possible
        int A_col = tile * TILE_SIZE + threadIdx.x;
        int B_row = tile * TILE_SIZE + threadIdx.y;

        // Coalesced loading
        if (row < N && A_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + A_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (B_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[B_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Unrolled computation
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            float a_reg[UNROLL_FACTOR];
            float b_reg[UNROLL_FACTOR];

            // Load into registers
            #pragma unroll
            for (int u = 0; u < UNROLL_FACTOR && k + u < TILE_SIZE; u++) {
                a_reg[u] = As[threadIdx.y][k + u];
                b_reg[u] = Bs[k + u][threadIdx.x];
            }

            // Compute
            #pragma unroll
            for (int u = 0; u < UNROLL_FACTOR && k + u < TILE_SIZE; u++) {
                sum += a_reg[u] * b_reg[u];
            }
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int block_size = TILE_SIZE;
    dim3 block(block_size, block_size);
    dim3 grid((N + block_size - 1) / block_size, (N + block_size - 1) / block_size);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

